type TypeCheck_SuggestionPair struct {
	suggestion string
	distance   int32
}

func (this *TypeCheck_SuggestionPair) zero_TypeCheck_SuggestionPair() {
	this.suggestion = nullstr_
}

func (this *TypeCheck_SuggestionPair) init_TypeCheck_SuggestionPair(suggestion string, distance int32) {
	this.suggestion = suggestion
	this.distance = distance
}

func new_TypeCheck_SuggestionPair(suggestion string, distance int32) *TypeCheck_SuggestionPair {
	this := &TypeCheck_SuggestionPair{}
	this.zero_TypeCheck_SuggestionPair()
	this.init_TypeCheck_SuggestionPair(suggestion, distance)
	return this
}

type TypeCheck_DebugTypeLogger struct {
	outer_      *TypeCheck
	typeLogFile *LogFile
	parentNode  Node
}

func (this *TypeCheck_DebugTypeLogger) init_TypeCheck_DebugTypeLogger() {
	this.typeLogFile = func() *LogFile {
		if this.outer_.compiler_.isDebugLoggingEnabled() {
			return this.outer_.compiler_.createOrReopenLog(Object_getClass(this), "types_logged_in_compiler.log", []string{})
		}
		return nil
	}()
}

func new_TypeCheck_DebugTypeLogger(outer_ *TypeCheck) *TypeCheck_DebugTypeLogger {
	this := &TypeCheck_DebugTypeLogger{}
	this.outer_ = outer_
	this.init_TypeCheck_DebugTypeLogger()
	return this
}

func (this *TypeCheck_DebugTypeLogger) maybeStartLoggingAt(n Node) {
	if !this.outer_.compiler_.isDebugLoggingEnabled() {
		return
	}
	if this.parentNode != 0 {
		return
	}
	var info *JSDocInfo = n.getJSDocInfo()
	if (info == nil) || !info.getLogTypeInCompiler() {
		return
	}
	this.parentNode = n
}

func (this *TypeCheck_DebugTypeLogger) stopLoggingIfThisIsWhereWeStarted(n Node) {
	if n == this.parentNode {
		this.parentNode = 0
	}
}

func (this *TypeCheck_DebugTypeLogger) close() {
	if this.typeLogFile != nil {
		this.typeLogFile.close()
	}
}

func (this *TypeCheck_DebugTypeLogger) maybeLogTypeOfNode(n Node) {
	if this.parentNode == 0 {
		return
	}
	if n.getJSType() == nil {
		return
	}
	this.typeLogFile.logString(n.toString_3(true, true, true))
}
